// Production-grade slugify for HiveFund URLs.
// Pipeline (in spec order): validate → transliterate → NFKD + strip marks →
// remove apostrophes → lowercase → split into [a-z0-9] words → join with
// separator → word-boundary truncation for maxLength.

const TRANSLITERATIONS = {
  "ß": "ss",
  "ẞ": "ss",
  "æ": "ae",
  "Æ": "AE", // lowercased later by stage 5
  "ø": "o",
  "Ø": "O",
  "œ": "oe",
  "Œ": "OE",
  "đ": "d",
  "Đ": "D",
  "ł": "l",
  "Ł": "L",
  "þ": "th",
  "Þ": "TH",
  "ð": "d",
  "Ð": "D",
};

// One character class covering exactly the transliteration keys.
const TRANSLIT_RE = /[ßẞæÆøØœŒđĐłŁþÞðÐ]/gu;

// Combining diacritical marks block (U+0300–U+036F).
const COMBINING_MARK_RE = /[\u0300-\u036F]/g;

// ASCII apostrophe and typographic apostrophe are deleted, not replaced.
const APOSTROPHE_RE = /['’]/g;

// Words are maximal runs of ASCII lowercase letters and digits.
const WORD_RE = /[a-z0-9]+/g;

const VALID_SEPARATORS = new Set(["-", "_", "."]);

function validateOptions(options) {
  if (options === undefined || options === null) {
    return { separator: "-", maxLength: undefined };
  }
  if (typeof options !== "object") {
    throw new TypeError(
      "options must be an object, undefined or null"
    );
  }
  const { separator, maxLength } = options;
  let sep = "-";
  if (separator !== undefined) {
    if (typeof separator !== "string" || !VALID_SEPARATORS.has(separator)) {
      throw new RangeError(
        'separator must be one of "-", "_", "."'
      );
    }
    sep = separator;
  }
  let max = undefined;
  if (maxLength !== undefined) {
    if (
      typeof maxLength !== "number" ||
      !Number.isInteger(maxLength) ||
      maxLength <= 0
    ) {
      throw new RangeError(
        "maxLength must be a positive integer"
      );
    }
    max = maxLength;
  }
  return { separator: sep, maxLength: max };
}

export function slugify(input, options) {
  // Rule 10: validate before doing any work.
  if (typeof input !== "string") {
    throw new TypeError("input must be a string");
  }
  const { separator, maxLength } = validateOptions(options);

  // Rule 1: transliterate before normalizing.
  let s = input.replace(TRANSLIT_RE, (ch) => TRANSLITERATIONS[ch]);

  // Rule 2: NFKD decomposition, then strip combining marks U+0300–U+036F.
  s = s.normalize("NFKD").replace(COMBINING_MARK_RE, "");

  // Rule 3: remove apostrophes without inserting a separator.
  s = s.replace(APOSTROPHE_RE, "");

  // Rule 4: lowercase.
  s = s.toLowerCase();

  // Rules 5–6, 8: words are non-empty runs of [a-z0-9]; everything else is a
  // boundary. Matching words directly collapses repeated separators and never
  // produces leading/trailing separators. No words → "".
  const words = s.match(WORD_RE);
  if (!words || words.length === 0) {
    return "";
  }

  // Rule 6: join with the separator.
  const slug = words.join(separator);

  // Rule 7: maxLength truncation on whole words.
  if (maxLength === undefined || slug.length <= maxLength) {
    return slug;
  }

  // Keep the longest prefix of whole words that fits. Each kept word after
  // the first costs one extra separator character.
  const kept = [];
  let length = 0;
  for (const word of words) {
    const added = word.length + (kept.length === 0 ? 0 : separator.length);
    if (length + added > maxLength) {
      break;
    }
    kept.push(word);
    length += added;
  }

  if (kept.length > 0) {
    return kept.join(separator);
  }

  // Even the first word alone exceeds maxLength: cut that word to maxLength
  // characters. It contains only [a-z0-9], so the result never ends with a
  // separator.
  return words[0].slice(0, maxLength);
}

export default slugify;

export function slugify(input, options) {
  // Validate input
  if (typeof input !== 'string') {
    throw new TypeError('Input must be a string');
  }
  // Validate options
  const opts = options || {};
  const separator = opts.separator === undefined ? '-' : opts.separator;
  const maxLength = opts.maxLength === undefined ? Infinity : opts.maxLength;
  if (!['-', '_', '.'].includes(separator)) {
    throw new RangeError("separator must be one of '-', '_', '.'");
  }
  if (typeof maxLength !== 'number' || !Number.isInteger(maxLength) || maxLength <= 0) {
    throw new RangeError('maxLength must be a positive integer');
  }

  // Rule 1: Transliteration before normalization
  const translitMap = {
    'ß': 'ss', 'ẞ': 'ss',
    'æ': 'ae', 'Æ': 'ae',
    'ø': 'o', 'Ø': 'o',
    'œ': 'oe', 'Œ': 'oe',
    'đ': 'd', 'Đ': 'd',
    'ł': 'l', 'Ł': 'l',
    'þ': 'th', 'Þ': 'th',
    'ð': 'd', 'Ð': 'd'
  };
  let processed = input.replace(/[ßẞæÆøØœŒđĐłŁþÞðÐ]/g, ch => translitMap[ch]);

  // Rule 2: NFKD normalization and remove combining marks
  processed = processed.normalize('NFKD');
  processed = processed.replace(/[\u0300-\u036f]/g, '');

  // Rule 3: Remove apostrophes (straight and curly) without separator
  processed = processed.replace(/['’]/g, '');

  // Rule 4: Lowercase
  processed = processed.toLowerCase();

  // Rule 5: Split into words on non [a-z0-9]
  const words = processed.split(/[^a-z0-9]+/).filter(word => word.length > 0);

  // Rule 6: Join with separator, no leading/trailing/repeated separators
  let slug = words.join(separator);

  // Rule 7: Apply maxLength truncation
  if (slug.length > maxLength) {
    // Find the longest prefix of whole words that fits
    let prefix = '';
    for (const word of words) {
      const candidate = prefix ? prefix + separator + word : word;
      if (candidate.length <= maxLength) {
        prefix = candidate;
      } else {
        break;
      }
    }
    if (prefix) {
      slug = prefix;
    } else {
      // Even the first word is too long, cut it to maxLength
      slug = words[0].slice(0, maxLength);
    }
  }

  // Rule 8: Empty result for empty or whitespace/punctuation-only input
  // (Already handled by words array being empty, but ensure empty string)
  if (slug.length === 0) {
    return '';
  }

  // Rule 9: Idempotency is inherent due to the pipeline
  return slug;
}

